const promise = new Promise((resolve, reject) => {
  setTimeout(() => {
    const success = true;
    if (success) {
      resolve('Data loaded!');
    } else {
      reject('Error occurred');
    }
  }, 1000);
});

promise
  .then(result => {
    console.log(result);
    return 'Processed: ' + result;
  })
  .then(processed => {
    console.log(processed);
  })
  .catch(error => {
    console.log('Error:', error);
  });
